function renderPresetLibrary(filter="all"){
 const root=$("presetLibrary");if(!root)return;root.replaceChildren();
 PRESET_CATALOG.filter(p=>filter==="all"||p.category===filter).forEach(p=>{
  const card=document.createElement("article"),swatch=document.createElement("div"),copy=document.createElement("div"),tag=document.createElement("small"),title=document.createElement("h4"),desc=document.createElement("p"),actions=document.createElement("div"),preview=document.createElement("button"),apply=document.createElement("button"),v=p.values||p.profile;
  card.className="preset-card preset-"+p.category;swatch.className="preset-swatch";swatch.style.setProperty("--preset-accent",v.accent);swatch.style.setProperty("--preset-secondary",v.secondary||v.atmosphere);swatch.style.setProperty("--preset-bg",v.background||v.atmosphere);
  copy.className="preset-card-copy";tag.textContent=p.tag;title.textContent=p.name;desc.textContent=p.description;copy.append(tag,title,desc);actions.className="preset-card-actions";
  const publishNow=document.createElement("button");preview.type=apply.type=publishNow.type="button";preview.className="btn";preview.textContent="Preview";apply.className="btn";apply.textContent="Save Draft";publishNow.className="btn primary";publishNow.textContent="Apply & Publish";
  preview.addEventListener("click",()=>{try{applyPreset(p);$("presetActionStatus").textContent=p.name+" loaded into the actual website preview. Not saved or published yet."}catch(e){$("presetActionStatus").textContent=e.message}});
  apply.addEventListener("click",async()=>{try{applyPreset(p);await save();$("presetActionStatus").textContent=p.name+" saved to your private draft. Review the right-side preview, then use Publish when ready."}catch(e){$("presetActionStatus").textContent=e.message||"Could not apply this preset."}});
  publishNow.addEventListener("click",async()=>{try{if(!confirm("Apply and publish "+p.name+" to the public 4FU website now? This updates settings/website.experience. Hosting files and existing festival settings remain untouched."))return;applyPreset(p);await save();if($("draftStatus").textContent!=="Private draft saved.")throw Error($("draftStatus").textContent||"Draft save failed.");await publish();$("presetActionStatus").textContent=p.name+" published. Refresh the public website to see the new experience."}catch(e){$("presetActionStatus").textContent=e.message||"Publish failed."}});
  actions.append(preview,apply,publishNow);card.append(swatch,copy,actions);root.append(card);
 });
}
function applyPreset(p){
 if(p.values)paint({...values(),...p.values,preset:"custom"});
 if(p.category==="festival"){const f={...p.profile,startAt:"",endAt:"",mode:"manual",enabled:true,priority:100,sound:false};festivalLibrary=festivalLibrary.filter(x=>x.id!==f.id).map(x=>x.mode==="manual"?{...x,enabled:false}:x);festivalLibrary.push(f);selectedFestival=f.id;renderFestivalOptions();selectFestival(f.id);queueWebsitePreview();return;}
 queueWebsitePreview();
}

function normaliseFestivals(input){if(!Array.isArray(input))return BUILTIN_FESTIVALS.map(x=>({...x}));const map=new Map(BUILTIN_FESTIVALS.map(x=>[x.id,{...x}]));input.forEach(x=>{if(x&&typeof x.id==="string"&&/^[a-z0-9-]{2,40}$/.test(x.id)&&map.has(x.id))map.set(x.id,{...map.get(x.id),...x});else if(x&&typeof x.id==="string"&&/^[a-z0-9-]{2,40}$/.test(x.id)&&x.custom===true)map.set(x.id,{...x})});return [...map.values()].slice(0,40)}
function renderFestivalOptions(){const s=$("festivalSelect");s.replaceChildren();festivalLibrary.forEach(f=>{const o=document.createElement("option");o.value=f.id;o.textContent=(f.custom?"✦ ":"")+f.name;s.append(o)})}
function selectFestival(id){const f=festivalLibrary.find(x=>x.id===id);if(!f)return;selectedFestival=id;$("festivalSelect").value=id;for(const [field,key] of [["festivalName","name"],["festivalLabel","label"],["festivalMessage","message"],["festivalStyle","style"],["festivalAccent","accent"],["festivalAtmosphere","atmosphere"],["festivalParticle","particle"],["festivalIntensity","intensity"],["festivalStart","startAt"],["festivalEnd","endAt"],["festivalMode","mode"],["festivalPriority","priority"]])$(field).value=f[key]??"";$("festivalEnabled").checked=!!f.enabled;$("festivalSound").checked=!!f.sound;paintFestivalPreview(f)}
function paintFestivalPreview(f){$("festivalPreview").style.setProperty("--festival-accent",f.accent||"#ffc15b");$("festivalPreview").style.setProperty("--festival-atmosphere",f.atmosphere||"#24170c");$("festivalPreviewName").textContent=f.name||"Festival";$("festivalPreviewMessage").textContent=f.message||""}
function collectFestivalPreview(){const base=festivalLibrary.find(x=>x.id===selectedFestival)||BUILTIN_FESTIVALS[0];return {...base,id:selectedFestival,name:$("festivalName").value.trim()||base.name,label:$("festivalLabel").value.trim()||base.label,message:$("festivalMessage").value.trim()||base.message,style:$("festivalStyle").value||base.style,accent:$("festivalAccent").value||base.accent,atmosphere:$("festivalAtmosphere").value||base.atmosphere,particle:$("festivalParticle").value||base.particle,intensity:$("festivalIntensity").value||base.intensity,startAt:$("festivalStart").value,endAt:$("festivalEnd").value,mode:$("festivalMode").value||base.mode,priority:Number($("festivalPriority").value)||base.priority,enabled:$("festivalEnabled").checked,sound:$("festivalSound").checked}}
function collectFestival(){const f={id:selectedFestival,custom:!!festivalLibrary.find(x=>x.id===selectedFestival)?.custom,name:$("festivalName").value.trim(),label:$("festivalLabel").value.trim(),message:$("festivalMessage").value.trim(),style:$("festivalStyle").value,accent:$("festivalAccent").value,atmosphere:$("festivalAtmosphere").value,particle:$("festivalParticle").value,intensity:$("festivalIntensity").value,startAt:$("festivalStart").value,endAt:$("festivalEnd").value,mode:$("festivalMode").value,priority:Math.max(0,Math.min(100,Number($("festivalPriority").value)||0)),enabled:$("festivalEnabled").checked,sound:$("festivalSound").checked};if(!f.name||!f.label||!f.message)throw Error("Festival name, label and message are required.");if(f.mode==="scheduled"&&f.startAt&&f.endAt&&new Date(f.endAt)<=new Date(f.startAt))throw Error("End date must be after start date.");if(f.mode==="scheduled"&&f.enabled&&(!f.startAt||!f.endAt))throw Error("Set both start and end times before enabling a scheduled festival.");return f}
function applyFestival(){try{const f=collectFestival(),i=festivalLibrary.findIndex(x=>x.id===f.id);if(i<0)throw Error("Festival profile not found.");festivalLibrary[i]=f;renderFestivalOptions();selectFestival(f.id);queueWebsitePreview();$("festivalStatus").textContent="Profile applied to this draft. Save draft to keep it."; }catch(e){$("festivalStatus").textContent=e.message}}
function addFestival(){if(festivalLibrary.length>=40){$("festivalStatus").textContent="Maximum 40 festival profiles reached.";return}const id="custom-"+Date.now().toString(36);festivalLibrary.push({id,name:"New Festival",label:"CELEBRATION",message:"A new celebration begins.",style:"custom",accent:"#ffc15b",atmosphere:"#24170c",particle:"spark",intensity:"medium",enabled:false,mode:"scheduled",startAt:"",endAt:"",priority:10,sound:false,custom:true});renderFestivalOptions();selectFestival(id);$("festivalStatus").textContent="Custom profile created. Edit its details and apply."}
function removeFestival(){const f=festivalLibrary.find(x=>x.id===selectedFestival);if(!f?.custom){$("festivalStatus").textContent="Built-in festivals cannot be removed; disable them instead.";return}festivalLibrary=festivalLibrary.filter(x=>x.id!==selectedFestival);renderFestivalOptions();selectFestival(festivalLibrary[0].id);$("festivalStatus").textContent="Custom profile removed from this draft."}
function installFieldGuides(){const guides={accent:"Changes the orange highlight used across the site: buttons, links and active accents.",secondary:"Changes the secondary highlight paired with the main accent.",background:"Changes the overall page background across the website.",surface:"Changes card, panel and navigation surface colours.",textColor:"Changes the main text colour across the website.",radius:"Changes corner roundness on cards, buttons and surfaces.",preset:"Applies a coordinated colour palette to the design controls.",brandName:"Updates the visible team/brand name and image alt text.",brandShortName:"Updates compact 4FU brand labels where supported.",brandTagline:"Updates the brand tagline where the site displays it.",browserTitle:"Changes the browser tab title and social preview title.",brandDescription:"Updates the search and social description metadata.",brandLogo:"Replaces the main website logo in the live preview.",contentEyebrow:"Small uppercase line above the homepage hero title.",contentTitle:"First line of the homepage hero heading.",contentTitleHighlight:"Highlighted second part of the homepage hero heading.",contentSubtitle:"Short heading directly below the hero title.",contentDescription:"Main paragraph in the homepage hero.",contentPrimaryText:"Text on the first hero call-to-action button.",contentPrimaryLink:"Destination opened by the first hero button.",contentSecondaryText:"Text on the second hero call-to-action button.",contentSecondaryLink:"Destination opened by the second hero button.",contentHeroBackground:"Background image behind the homepage hero content.",festivalStyle:"Chooses the visual art direction for this festival only.",festivalParticle:"Chooses the festival-specific atmosphere effect.",festivalIntensity:"Controls how many decorative elements appear.",festivalStart:"Start time for automatic festival activation.",festivalEnd:"End time for automatic festival deactivation.",motionEnabled:"Turns the site's subtle ambient motion layer on or off.",ambientEffect:"Selects the ambient particles shown across the homepage.",loaderPreset:"Chooses how the opening brand reveal is presented.",loaderDuration:"Minimum time the opening loader remains visible."};Object.assign(guides,{brandCompactLogo:"Compact or mobile logo used where a smaller brand mark is displayed.",brandFavicon:"Small icon shown in browser tabs and bookmarks.",brandOgImage:"Image used when the website link is shared on social platforms.",festivalSelect:"Choose which festival profile you are editing; changes below apply only to this profile.",festivalName:"Internal display name for this festival experience.",festivalLabel:"Short celebration label shown in the festival welcome message.",festivalMessage:"The festival greeting visitors see on the website.",festivalAccent:"Main highlight colour used by this festival's artwork.",festivalAtmosphere:"Background glow and atmosphere colour for this festival.",festivalIntensity:"Controls the amount of festival particles or visual elements.",festivalMode:"Choose automatic date-based activation or manual activation.",festivalPriority:"Higher priority wins if two enabled festival schedules overlap.",festivalEnabled:"Allows this festival profile to activate when its mode and dates match.",festivalSound:"Optional audio setting; currently kept off unless explicitly enabled.",fontFamily:"Changes the typography system across supported website headings and text.",headerStyle:"Changes the navigation bar between glass, solid and minimal treatments.",footerStyle:"Changes the visual treatment of the site footer.",cardStyle:"Changes supported cards between elevated, glass, flat and outlined styles.",buttonStyle:"Changes supported buttons between solid, gradient, outline and glass styles.",shadowStyle:"Controls the depth of supported card shadows.",contentWidth:"Sets the maximum width of supported homepage content containers.",sectionSpacing:"Changes vertical spacing between major homepage sections.",borderStyle:"Controls borders on supported cards and panels.",motionLevel:"Sets the site's overall motion intensity while respecting reduced-motion settings.",motionIntensity:"Controls how many ambient decorative particles are shown.",motionSpeed:"Controls the speed of ambient movement.",motionOpacity:"Controls the visibility of ambient decorative particles.",loaderEnabled:"Turns the opening 4FU loader on or off.",loaderText:"Main title displayed in the opening loader.",loaderSubtext:"Supporting line displayed under the loader title.",loaderBackground:"Background colour behind the opening loader animation.",loaderLogo:"Optional logo shown in the opening loader; blank keeps the existing logo.",assetFile:"Select an image, banner, texture or GIF to add to the private asset library.",assetCategory:"Organises the asset by its intended website use.",assetName:"Friendly name shown for this asset inside the Studio library.",assetUrl:"Add an existing HTTPS image URL without uploading a file.",assetUrlName:"Name used to identify the external asset in the library.",contentAboutEyebrow:"Small label above the homepage About section heading.",contentAboutTitle:"Main heading of the homepage About section.",contentAboutDescription:"Paragraph describing the 4FU team in the homepage About section.",contentAboutButtonText:"Text displayed on the About section button.",contentAboutButtonLink:"Destination opened by the About section button."});Object.entries(guides).forEach(([id,help])=>{const field=$(id),label=field?.closest("label");if(!label||label.querySelector(".field-help"))return;const note=document.createElement("small");note.className="field-help";note.textContent=help;label.append(note);field.setAttribute("aria-describedby",id+"Help");note.id=id+"Help"});const intro=document.createElement("div");intro.className="studio-instructions";intro.innerHTML="<b>How to use this Studio</b><span>1. Choose a section. 2. Change any field. 3. Watch the full website preview above update automatically. 4. Save Draft to keep changes privately. Publish only when you are satisfied.</span><span class='studio-live-note'>Preview = real 4FU homepage · private only · no public changes until Publish.</span>";const tabs=document.querySelector(".studio-tabs");if(tabs&&!document.querySelector(".studio-instructions"))tabs.after(intro)}
